<?php $pageTitle='Review curriculum import'; ?>
<section class="page-heading"><div><p class="eyebrow">Validation preview</p><h1>Review programme subjects</h1><p><?= e($batch['original_filename']) ?> contains <?= number_format((int)$batch['total_rows']) ?> curriculum rows.</p></div><a class="secondary-button" href="<?= e(url('courses/import')) ?>">Upload another file</a></section>
