<section class="import-summary"><article><span>Ready</span><strong><?= number_format((int)$batch['valid_rows']) ?></strong></article><article><span>Invalid</span><strong><?= number_format((int)$batch['invalid_rows']) ?></strong></article><article><span>Status</span><strong><?= e(ucfirst($batch['status'])) ?></strong></article></section>
<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Row</th><th>Programme</th><th>Semester</th><th>Subject code</th><th>Subject name</th><th>Category</th><th>Validation</th><th>Messages</th></tr></thead><tbody><?php foreach($rows as $row):$data=json_decode($row['normalized_data'],true);$messages=json_decode($row['validation_messages'],true)?:[];?><tr><td><?= (int)$row['row_number'] ?></td><td><strong><?= e($data['programme_code']??'') ?></strong></td><td><?= (int)($data['semester']??0) ?></td><td><strong><?= e($data['code']??'') ?></strong></td><td><?= e($data['name']??'') ?></td><td><?= e(ucfirst($data['category']??'')) ?></td><td><span class="status-label <?= e($row['validation_status']) ?>"><?= e(ucfirst($row['validation_status'])) ?></span></td><td><?= e(implode(' ',$messages)?:'Ready to import') ?></td></tr><?php endforeach;?></tbody></table></div></section>
